import{_ as a,o as i,c as t,a5 as n}from"./chunks/framework.a5no_H3L.js";const k=JSON.parse('{"title":"部署：从开发到生产","description":"本页面向已经把 FastAPI 服务写好、想部署上线的读者，回答一个问题：怎么把 FastAPI 应用稳定地跑在生产环境。前置知识是 FastAPI 后端开发。","frontmatter":{"type":"howto","level":"advanced"},"headers":[],"relativePath":"python/06-production/chapter-01-deployment.md","filePath":"python/06-production/chapter-01-deployment.md"}'),e={name:"python/06-production/chapter-01-deployment.md"};function p(l,s,r,o,h,d){return i(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="部署-从开发到生产" tabindex="-1" data-src-line="2" data-src-file="python/06-production/chapter-01-deployment.md">部署：从开发到生产 <a class="header-anchor" href="#部署-从开发到生产" aria-label="Permalink to &quot;部署：从开发到生产&quot;">​</a></h1><p data-src-line="4" data-src-file="python/06-production/chapter-01-deployment.md">本页面向已经把 FastAPI 服务写好、想部署上线的读者，回答一个问题：怎么把 FastAPI 应用稳定地跑在生产环境。前置知识是 <a href="./../04-fastapi/chapter-01-fastapi-core.html">FastAPI 后端开发</a>。</p><h2 id="_1-asgi-服务器" tabindex="-1" data-src-line="6" data-src-file="python/06-production/chapter-01-deployment.md">1. ASGI 服务器 <a class="header-anchor" href="#_1-asgi-服务器" aria-label="Permalink to &quot;1. ASGI 服务器&quot;">​</a></h2><p data-src-line="8" data-src-file="python/06-production/chapter-01-deployment.md">FastAPI 应用是 ASGI 应用，需要一个 ASGI 服务器来运行。开发时用 <code>uvicorn --reload</code>，生产去掉 <code>--reload</code> 并加多进程：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uvicorn main:app --host 0.0.0.0 --port 8000 --workers 4</span></span></code></pre></div><ul data-src-line="14" data-src-file="python/06-production/chapter-01-deployment.md"><li data-src-line="14" data-src-file="python/06-production/chapter-01-deployment.md"><code>--host 0.0.0.0</code> 监听所有网卡，允许外部访问。</li><li data-src-line="15" data-src-file="python/06-production/chapter-01-deployment.md"><code>--workers 4</code> 启动 4 个 worker 进程，利用多核。</li><li data-src-line="16" data-src-file="python/06-production/chapter-01-deployment.md">生产<strong>不要</strong>用 <code>--reload</code>（它用于开发时热重载，会拖慢性能）。</li></ul><p data-src-line="18" data-src-file="python/06-production/chapter-01-deployment.md">worker 数量一般设为 CPU 核心数的 1~4 倍，具体按负载和内存调。IO 密集应用可以多开，CPU 密集受 GIL 限制，多 worker 也难线性提升。</p><h2 id="_2-gunicorn-管理-worker" tabindex="-1" data-src-line="20" data-src-file="python/06-production/chapter-01-deployment.md">2. Gunicorn 管理 worker <a class="header-anchor" href="#_2-gunicorn-管理-worker" aria-label="Permalink to &quot;2. Gunicorn 管理 worker&quot;">​</a></h2><p data-src-line="22" data-src-file="python/06-production/chapter-01-deployment.md">生产常用 Gunicorn 作为进程管理器，用它拉起多个 uvicorn worker：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pip install gunicorn</span></span>
<span class="line"><span>gunicorn -k uvicorn.workers.UvicornWorker -w 4 -b 0.0.0.0:8000 main:app</span></span></code></pre></div><ul data-src-line="29" data-src-file="python/06-production/chapter-01-deployment.md"><li data-src-line="29" data-src-file="python/06-production/chapter-01-deployment.md"><code>-k uvicorn.workers.UvicornWorker</code> 指定 worker 类型为 uvicorn。</li><li data-src-line="30" data-src-file="python/06-production/chapter-01-deployment.md"><code>-w 4</code> worker 数量，<code>-b</code> 绑定地址。</li></ul><p data-src-line="32" data-src-file="python/06-production/chapter-01-deployment.md">Gunicorn 负责进程管理（fork、重启崩溃的 worker、平滑重启），uvicorn worker 负责真正处理请求。两者组合是 FastAPI 最常见的生产部署方式。</p><h2 id="_3-nginx-反向代理" tabindex="-1" data-src-line="34" data-src-file="python/06-production/chapter-01-deployment.md">3. Nginx 反向代理 <a class="header-anchor" href="#_3-nginx-反向代理" aria-label="Permalink to &quot;3. Nginx 反向代理&quot;">​</a></h2><p data-src-line="36" data-src-file="python/06-production/chapter-01-deployment.md">生产通常在前面加一层 Nginx：处理 TLS、静态文件、负载均衡，把请求转发给后面的 uvicorn/gunicorn：</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    listen </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    server_name </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">example.com;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    location</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> / </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_pass </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:8000;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Host $host;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Forwarded-For $proxy_add_x_forwarded_for;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p data-src-line="51" data-src-file="python/06-production/chapter-01-deployment.md">FastAPI 应用监听本机 8000 端口，Nginx 对外提供服务。TLS 证书（HTTPS）也在 Nginx 这一层配置，应用本身不需要处理 HTTPS。</p><h2 id="_4-容器化" tabindex="-1" data-src-line="53" data-src-file="python/06-production/chapter-01-deployment.md">4. 容器化 <a class="header-anchor" href="#_4-容器化" aria-label="Permalink to &quot;4. 容器化&quot;">​</a></h2><p data-src-line="55" data-src-file="python/06-production/chapter-01-deployment.md">用 Docker 打包，保证环境一致。一个最小的 Dockerfile：</p><div class="language-dockerfile vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> python:3.13-slim</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WORKDIR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /app</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> requirements.txt .</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pip install --no-cache-dir -r requirements.txt</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> . .</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">EXPOSE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 8000</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CMD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gunicorn&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-k&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;uvicorn.workers.UvicornWorker&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-w&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;4&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-b&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.0.0.0:8000&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;main:app&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p data-src-line="67" data-src-file="python/06-production/chapter-01-deployment.md">要点：先 <code>COPY requirements.txt</code> 再 <code>pip install</code>，利用 Docker 层缓存；<code>CMD</code> 用生产命令而不是 <code>--reload</code>。</p><h2 id="_5-配置与环境变量" tabindex="-1" data-src-line="69" data-src-file="python/06-production/chapter-01-deployment.md">5. 配置与环境变量 <a class="header-anchor" href="#_5-配置与环境变量" aria-label="Permalink to &quot;5. 配置与环境变量&quot;">​</a></h2><p data-src-line="71" data-src-file="python/06-production/chapter-01-deployment.md">不同环境（开发/测试/生产）的配置不同，用环境变量注入，不硬编码：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> os</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DATABASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> os.environ.get(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;DATABASE_URL&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;sqlite:///app.db&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">SECRET_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> os.environ[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;SECRET_KEY&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 生产必须提供，缺失则启动失败</span></span></code></pre></div><p data-src-line="80" data-src-file="python/06-production/chapter-01-deployment.md">数据库地址、密钥、第三方服务的 key 都通过环境变量传入。密码、令牌这类敏感值绝不写进代码或镜像。</p><h2 id="_6-这一章要记住的结论" tabindex="-1" data-src-line="82" data-src-file="python/06-production/chapter-01-deployment.md">6. 这一章要记住的结论 <a class="header-anchor" href="#_6-这一章要记住的结论" aria-label="Permalink to &quot;6. 这一章要记住的结论&quot;">​</a></h2><p data-src-line="84" data-src-file="python/06-production/chapter-01-deployment.md">FastAPI 用 ASGI 服务器运行，生产用 <code>gunicorn -k uvicorn.workers.UvicornWorker</code> 或 <code>uvicorn --workers</code> 多进程部署；前面加 Nginx 处理 HTTPS 和负载均衡；用 Docker 打包；配置通过环境变量注入。</p>`,26)])])}const E=a(e,[["render",p]]);export{k as __pageData,E as default};
